import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"绵","description":"","frontmatter":{"title":"绵","date":"2026-11-09T00:00:00.000Z","seq":3,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/绵.md","filePath":"blogs/诗经·大雅/绵.md"}'),p={name:"blogs/诗经·大雅/绵.md"};function c(l,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="绵" tabindex="-1">绵 <a class="header-anchor" href="#绵" aria-label="Permalink to &quot;绵&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　文王之什</p><div class="poem"><p class="poem-stanza">绵绵瓜瓞。民之初生，自土沮漆。古公亶父，陶复陶冗，未有家室。</p><p class="poem-stanza">古公亶父，来朝走马。率西水浒，至于岐下。爰及姜女，聿来胥宇。</p><p class="poem-stanza">周原膴膴，堇荼如饴。爰始爰谋，爰契我龟，曰止曰时，筑室于兹。</p><p class="poem-stanza">乃慰乃止，乃左乃右，乃疆乃理，乃宣乃亩。自西徂东，周爰执事。</p><p class="poem-stanza">乃召司空，乃召司徒，俾立室家。其绳则直，缩版以载，作庙翼翼。</p><p class="poem-stanza">捄之陾陾，度之薨薨，筑之登登，削屡冯冯。百堵皆兴，鼛鼓弗胜。</p><p class="poem-stanza">乃立皋门，皋门有伉。乃立应门，应门将将。乃立冢土，戎丑攸行。</p><p class="poem-stanza">四不殄厥愠，亦不陨厥问。柞棫拔矣，行道兑矣。混夷駾矣，维其喙矣！</p><p class="poem-stanza">虞芮质厥成，文王蹶厥生。予曰有疏附，予曰有先后。予曰有奔奏，予曰有御侮！</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
